// 사운드 효과를 위한 AudioContext 생성
const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();

// 테트리스 배경 음악 노트와 타이밍
const tetrisTheme = {
  notes: [
    { note: 'E5', duration: 0.25 }, { note: 'B4', duration: 0.125 }, { note: 'C5', duration: 0.125 },
    { note: 'D5', duration: 0.25 }, { note: 'C5', duration: 0.125 }, { note: 'B4', duration: 0.125 },
    { note: 'A4', duration: 0.25 }, { note: 'A4', duration: 0.125 }, { note: 'C5', duration: 0.125 },
    { note: 'E5', duration: 0.25 }, { note: 'D5', duration: 0.125 }, { note: 'C5', duration: 0.125 },
    { note: 'B4', duration: 0.375 }, { note: 'C5', duration: 0.125 },
    { note: 'D5', duration: 0.25 }, { note: 'E5', duration: 0.25 },
    { note: 'C5', duration: 0.25 }, { note: 'A4', duration: 0.25 },
    { note: 'A4', duration: 0.375 }, { note: 'rest', duration: 0.125 }
  ],
  tempo: 80
};

// 음계 주파수 매핑
const noteFrequencies: { [key: string]: number } = {
  'A4': 440.00, 'B4': 493.88, 'C5': 523.25, 'D5': 587.33, 'E5': 659.25
};

let bgMusicLoop: number | null = null;

// 배경 음악 재생
function playBackgroundMusic() {
  if (bgMusicLoop) return;

  let currentTime = audioContext.currentTime;
  const gainNode = audioContext.createGain();
  gainNode.connect(audioContext.destination);
  gainNode.gain.value = 0.2; // 배경 음악 볼륨

  function playNote(noteInfo: { note: string; duration: number }, time: number) {
    if (noteInfo.note === 'rest') return;

    const oscillator = audioContext.createOscillator();
    const noteGain = audioContext.createGain();

    oscillator.connect(noteGain);
    noteGain.connect(gainNode);

    oscillator.type = 'sine';
    oscillator.frequency.value = noteFrequencies[noteInfo.note];

    noteGain.gain.setValueAtTime(0, time);
    noteGain.gain.linearRampToValueAtTime(0.3, time + 0.05);
    noteGain.gain.linearRampToValueAtTime(0, time + noteInfo.duration - 0.05);

    oscillator.start(time);
    oscillator.stop(time + noteInfo.duration);
  }

  function playTheme() {
    tetrisTheme.notes.forEach((noteInfo, index) => {
      playNote(noteInfo, currentTime);
      currentTime += noteInfo.duration * (60 / tetrisTheme.tempo);
    });

    // 루프 설정
    bgMusicLoop = window.setTimeout(playTheme, 
      (currentTime - audioContext.currentTime) * 1000);
  }

  playTheme();
}

// 배경 음악 정지
function stopBackgroundMusic() {
  if (bgMusicLoop) {
    clearTimeout(bgMusicLoop);
    bgMusicLoop = null;
  }
}

// 테트리스 스타일의 사운드 생성 함수
function createTetrisSound(type: 'move' | 'rotate' | 'drop' | 'clear' | 'gameOver') {
  const oscillator = audioContext.createOscillator();
  const gainNode = audioContext.createGain();

  oscillator.connect(gainNode);
  gainNode.connect(audioContext.destination);

  switch (type) {
    case 'move':
      // 더 부드러운 이동음
      oscillator.type = 'sine';
      oscillator.frequency.value = 587.33; // D5
      gainNode.gain.setValueAtTime(0, audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(0.15, audioContext.currentTime + 0.02);
      gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.1);
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.1);
      break;

    case 'rotate':
      // 더 경쾌한 회전음
      oscillator.type = 'sine';
      oscillator.frequency.value = 783.99; // G5
      gainNode.gain.setValueAtTime(0, audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(0.15, audioContext.currentTime + 0.02);
      gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.12);
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.12);
      break;

    case 'drop':
      // 부드러운 낙하음
      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(523.25, audioContext.currentTime); // C5
      oscillator.frequency.linearRampToValueAtTime(261.63, audioContext.currentTime + 0.15); // C4
      gainNode.gain.setValueAtTime(0.2, audioContext.currentTime);
      gainNode.gain.linearRampToValueAtTime(0, audioContext.currentTime + 0.15);
      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + 0.15);
      break;

    case 'clear':
      // 경쾌한 라인 제거음
      oscillator.type = 'sine';
      const clearDuration = 0.3;

      // 상승하는 아르페지오 효과
      [523.25, 659.25, 783.99, 1046.50].forEach((freq, i) => { // C5, E5, G5, C6
        const noteOsc = audioContext.createOscillator();
        const noteGain = audioContext.createGain();

        noteOsc.connect(noteGain);
        noteGain.connect(audioContext.destination);

        noteOsc.type = 'sine';
        noteOsc.frequency.value = freq;

        const startTime = audioContext.currentTime + (i * 0.05);
        noteGain.gain.setValueAtTime(0, startTime);
        noteGain.gain.linearRampToValueAtTime(0.2, startTime + 0.05);
        noteGain.gain.linearRampToValueAtTime(0, startTime + 0.2);

        noteOsc.start(startTime);
        noteOsc.stop(startTime + 0.2);
      });
      break;

    case 'gameOver':
      // 부드러운 게임오버 음
      oscillator.type = 'sine';
      const startFreq = 523.25; // C5
      const duration = 1.0;
      const steps = 6;

      for (let i = 0; i < steps; i++) {
        const time = audioContext.currentTime + (i * duration / steps);
        oscillator.frequency.setValueAtTime(startFreq / Math.pow(1.5, i/2), time);
        gainNode.gain.setValueAtTime(0.2, time);
        gainNode.gain.linearRampToValueAtTime(0, time + duration / steps - 0.05);
      }

      oscillator.start(audioContext.currentTime);
      oscillator.stop(audioContext.currentTime + duration);
      break;
  }
}

export const sounds = {
  move: () => createTetrisSound('move'),
  rotate: () => createTetrisSound('rotate'),
  drop: () => createTetrisSound('drop'),
  clear: () => createTetrisSound('clear'),
  gameOver: () => createTetrisSound('gameOver'),
  startMusic: () => playBackgroundMusic(),
  stopMusic: () => stopBackgroundMusic()
};
